import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { TypeOrmModule } from '@nestjs/typeorm';
import { GraphQLModule } from '@nestjs/graphql';
import { ApolloDriver, ApolloDriverConfig } from '@nestjs/apollo';
import { join } from 'path';
import * as Joi from 'joi';
import { ThrottlerModule } from '@nestjs/throttler';

import { appConfig } from './config/app.config';
import { redisConfig } from './config/redis.config';
import { rabbitmqConfig } from './config/rabbitmq.config';
import { HealthModule } from './health/health.module';
import { AuthModule } from './modules/auth/auth.module';
import { UserModule } from './modules/user/user.module';
import { SkillModule } from './modules/skill/skill.module';
import { MatchModule } from './modules/match/match.module';
import { SessionModule } from './modules/session/session.module';
import { NotificationModule } from './modules/notification/notification.module';
import { AiModule } from './modules/ai/ai.module';
import { DataloaderModule } from './modules/dataloader/dataloader.module';
import { CacheModule } from './modules/cache/cache.module';
import { MessageModule } from './modules/message/message.module';
import { ReviewModule } from './modules/review/review.module';
import { APP_GUARD } from '@nestjs/core';
import { JwtAuthGuard } from './common/guards/jwt-auth.guard';
import { RolesGuard } from './common/guards/roles.guard';
import { RateLimitGuard } from './modules/cache/rate-limit.guard';

@Module({
  imports: [
    // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Throttler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    ThrottlerModule.forRoot([{ ttl: 60000, limit: 50 }]),

    // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Config ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    ConfigModule.forRoot({
      isGlobal: true,
      load: [appConfig, redisConfig, rabbitmqConfig],
      validationSchema: Joi.object({
        PORT: Joi.number().default(3001),
        NODE_ENV: Joi.string()
          .valid('development', 'production', 'test')
          .default('development'),
        DATABASE_URL: Joi.string().required(),
        REDIS_URL: Joi.string().required(),
        RABBITMQ_URL: Joi.string().required(),
        JWT_SECRET: Joi.string().min(32).required(),
        JWT_REFRESH_SECRET: Joi.string().min(32).required(),
        GEMINI_API_KEY: Joi.string().required(),
        FRONTEND_URL: Joi.string().default('http://localhost:3000'),
      }),
      validationOptions: { allowUnknown: true, abortEarly: false },
    }),

    // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Database ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    TypeOrmModule.forRoot({
      type: 'postgres',
      url: process.env.DATABASE_URL,
      ssl:
        process.env.NODE_ENV === 'production'
          ? { rejectUnauthorized: false }
          : false,
      autoLoadEntities: true,
      synchronize: process.env.NODE_ENV !== 'production',
      logging: false,
    }),

    // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ GraphQL ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    GraphQLModule.forRoot<ApolloDriverConfig>({
      driver: ApolloDriver,
      autoSchemaFile: join(process.cwd(), 'src/schema.gql'),
      sortSchema: true,
      playground: process.env.NODE_ENV !== 'production',
      formatError: (error) => {
        return {
          message: error.message,
          code: error.extensions?.code || 'INTERNAL_SERVER_ERROR',
        };
      },
      subscriptions: {
        'graphql-ws': true,
      },
      context: ({
        req,
        res,
        connectionParams,
      }: {
        req?: Record<string, any>;
        res?: any;
        connectionParams?: Record<string, any>;
      }) => {
        const ctxReq = req || { headers: {} };
        if (connectionParams) {
          const normalizedHeaders = Object.keys(connectionParams).reduce(
            (acc, key) => {
              acc[key.toLowerCase()] = connectionParams[key];
              return acc;
            },
            {} as Record<string, any>,
          );
          ctxReq.headers = {
            ...(ctxReq.headers as Record<string, any>),
            ...normalizedHeaders,
          };
          ctxReq.connectionParams = connectionParams;
          if (!ctxReq.get) {
            ctxReq.get = function (this: any, name: string) {
              const headers = this.headers as Record<string, any>;
              return headers[name.toLowerCase()];
            };
          }
        }
        return { req: ctxReq, res };
      },
    }),
    HealthModule,
    AuthModule,
    UserModule,
    SkillModule,
    MatchModule,
    SessionModule,
    NotificationModule,
    AiModule,
    DataloaderModule,
    CacheModule,
    MessageModule,
    ReviewModule,
  ],
  providers: [
    {
      provide: APP_GUARD,
      useClass: JwtAuthGuard,
    },
    {
      provide: APP_GUARD,
      useClass: RolesGuard,
    },
    {
      provide: APP_GUARD,
      useClass: RateLimitGuard,
    },
  ],
})
export class AppModule {}

import { IoAdapter } from '@nestjs/platform-socket.io';
import { ServerOptions } from 'socket.io';
import { createAdapter } from '@socket.io/redis-adapter';
import { Redis } from 'ioredis';

export class RedisIoAdapter extends IoAdapter {
  private adapterConstructor: ReturnType<typeof createAdapter>;

  async connectToRedis(redisUrl: string): Promise<void> {
    const pubClient = new Redis(redisUrl);
    const subClient = pubClient.duplicate();
    await Promise.all([
      pubClient.connect().catch(() => {}),
      subClient.connect().catch(() => {}),
    ]); // ioredis auto connects but this ensures promise resolution if preferred
    this.adapterConstructor = createAdapter(pubClient, subClient);
  }

  createIOServer(port: number, options?: ServerOptions): unknown {
    const server = super.createIOServer(port, options);
    const s = server as { adapter: (arg: any) => void };
    s.adapter(this.adapterConstructor);
    return server;
  }
}

import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { GqlExecutionContext } from '@nestjs/graphql';

export const CurrentUser = createParamDecorator(
  (_data: unknown, context: ExecutionContext) => {
    const ctx = GqlExecutionContext.create(context);
    const req = ctx.getContext().req as { user?: unknown };
    return req.user;
  },
);

import { Catch, ArgumentsHost, Logger } from '@nestjs/common';
import { GqlExceptionFilter as NestGqlExceptionFilter } from '@nestjs/graphql';
import { GraphQLError } from 'graphql';

@Catch()
export class GqlExceptionFilter implements NestGqlExceptionFilter {
  private readonly logger = new Logger(GqlExceptionFilter.name);

  catch(exception: unknown): GraphQLError {
    if (exception instanceof GraphQLError) {
      return exception;
    }

    if (exception instanceof Error) {
      const exceptionWithResponse = exception as {
        getResponse?: () => unknown;
        status?: number;
      };
      const response = exceptionWithResponse.getResponse?.();
      let message = exception.message;

      if (typeof response === 'object' && response !== null) {
        const res = response as { message?: string | string[] };
        message = Array.isArray(res.message)
          ? res.message[0]
          : (res.message ?? exception.message);
      }

      this.logger.error(`Unhandled exception: ${message}`, exception.stack);

      return new GraphQLError(message, {
        extensions: {
          code:
            exceptionWithResponse.status === 400
              ? 'BAD_USER_INPUT'
              : 'INTERNAL_SERVER_ERROR',
          response,
          timestamp: new Date().toISOString(),
        },
      });
    }

    this.logger.error('Unknown exception', String(exception));
    return new GraphQLError('An unexpected error occurred', {
      extensions: { code: 'INTERNAL_SERVER_ERROR' },
    });
  }
}

import {
  Injectable,
  ExecutionContext,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { AuthGuard } from '@nestjs/passport';
import { GqlExecutionContext } from '@nestjs/graphql';
import { IS_PUBLIC_KEY } from '../decorators/public.decorator';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector) {
    super();
  }

  async canActivate(context: ExecutionContext): Promise<boolean> {
    if (context.getType() === 'rpc') return true;

    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      // For public routes: still try to authenticate so @CurrentUser() gets populated,
      // but don't block the request if auth fails (returns null for user).
      try {
        return (await super.canActivate(context)) as boolean;
      } catch {
        return true;
      }
    }

    return (await super.canActivate(context)) as boolean;
  }

  getRequest(context: ExecutionContext): Request {
    if (context.getType().toString() === 'graphql') {
      const ctx = GqlExecutionContext.create(context);
      return ctx.getContext().req as Request;
    }
    return context.switchToHttp().getRequest();
  }

  handleRequest<TUser = any>(
    err: any,
    user: TUser,
    _info: any,
    context: ExecutionContext,
  ): TUser {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      if (err || !user) return null as any;
      return user;
    }
    if (err || !user) throw err || new UnauthorizedException();
    return user;
  }
}

import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { GqlExecutionContext } from '@nestjs/graphql';
import { ROLES_KEY, Role } from '../decorators/roles.decorator';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    if (context.getType() === 'rpc') return true;

    const requiredRoles = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (!requiredRoles) return true;

    const ctx = GqlExecutionContext.create(context);
    const req = ctx.getContext().req as { user?: { role?: string } };
    if (!req || !req.user) return false;

    const userRole = req.user.role || 'user';
    return requiredRoles.some((role) => userRole === role);
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Logger,
} from '@nestjs/common';
import { GqlExecutionContext } from '@nestjs/graphql';
import { Observable, tap } from 'rxjs';

@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  private readonly logger = new Logger('GraphQL');

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const ctx = GqlExecutionContext.create(context);
    const info = ctx.getInfo();
    const start = Date.now();

    return next.handle().pipe(
      tap(() => {
        const elapsed = Date.now() - start;
        this.logger.log(
          `${info?.parentType?.name}.${info?.fieldName} ΓÇö ${elapsed}ms`,
        );
      }),
    );
  }
}

