import {
  Controller,
  Sse,
  Param,
  Query,
  Body,
  Post,
  Get,
  UnauthorizedException,
  Req,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Observable } from 'rxjs';
import { AiService } from './ai.service';
import { Message } from '../message/message.entity';
import { Review } from '../review/review.entity';
import { Public } from '../../common/decorators/public.decorator';
import { Session } from '../session/session.entity';

const MIN_MESSAGES = 6;
const MIN_TOTAL_WORDS = 20;

@Controller('ai')
export class AiController {
  constructor(
    private readonly aiService: AiService,
    @InjectRepository(Message)
    private readonly messageRepository: Repository<Message>,
    @InjectRepository(Review)
    private readonly reviewRepository: Repository<Review>,
    @InjectRepository(Session)
    private readonly sessionRepository: Repository<Session>,
  ) {}

  @Public()
  @Sse('session/:id/summary/stream')
  streamSummary(
    @Param('id') sessionId: string,
    @Req() req: any,
  ): Observable<MessageEvent> {
    return new Observable<MessageEvent>((subscriber) => {
      (async () => {
        try {
          const userId = req.user?.id || req.user?.sub;
          if (userId) {
            const session = await this.sessionRepository.findOne({
              where: { id: sessionId },
              select: ['id', 'participant1Id', 'participant2Id'],
            });
            if (
              session &&
              session.participant1Id !== userId &&
              session.participant2Id !== userId
            ) {
              subscriber.error(
                new UnauthorizedException(
                  'You are not a participant of this session',
                ),
              );
              return;
            }
          }
          const messages = await this.messageRepository.find({
            where: { sessionId },
            order: { createdAt: 'ASC' },
            relations: ['sender'],
          });

          const transcript = this.buildTranscript(messages);
          const wordCount = transcript
            ? transcript.split(/\s+/).filter(Boolean).length
            : 0;

          // Refuse to summarise gibberish ΓÇö protects users from hallucinated recaps and saves quota.
          if (messages.length < MIN_MESSAGES || wordCount < MIN_TOTAL_WORDS) {
            subscriber.next({
              data: `Not enough chat yet to recap (${messages.length} message${
                messages.length === 1 ? '' : 's'
              }, ${wordCount} word${wordCount === 1 ? '' : 's'}). Aim for at least ${MIN_MESSAGES} substantive messages, then try again.`,
            } as MessageEvent);
            return;
          }

          const generator = this.aiService.streamSessionSummary(transcript);
          for await (const chunk of generator) {
            subscriber.next({ data: chunk } as MessageEvent);
          }
        } catch (e) {
          subscriber.error(e);
        } finally {
          subscriber.next({ data: '[DONE]' } as MessageEvent);
          subscriber.complete();
        }
      })();
    });
  }

  @Public()
  @Sse('agenda')
  streamAgenda(
    @Query('offered') offeredTitle: string,
    @Query('wanted') wantedTitle: string,
    @Query('duration') durationParam: string,
  ): Observable<MessageEvent> {
    return new Observable<MessageEvent>((subscriber) => {
      (async () => {
        try {
          const duration = parseInt(durationParam || '60', 10) || 60;
          const generator = this.aiService.generateAgendaStream(
            offeredTitle || 'Skill A',
            wantedTitle || 'Skill B',
            duration,
          );
          for await (const chunk of generator) {
            subscriber.next({ data: chunk } as MessageEvent);
          }
        } catch (e) {
          subscriber.error(e);
        } finally {
          subscriber.next({ data: '[DONE]' } as MessageEvent);
          subscriber.complete();
        }
      })();
    });
  }

  @Public()
  @Sse('user/:userId/skill/:skillId/reviews/summary/stream')
  streamSkillReviewsSummary(
    @Param('userId') userId: string,
    @Param('skillId') skillId: string,
    @Query('title') skillTitle: string,
  ): Observable<MessageEvent> {
    return new Observable<MessageEvent>((subscriber) => {
      (async () => {
        try {
          const reviews = await this.reviewRepository.find({
            where: { revieweeId: userId, skillId },
            order: { createdAt: 'DESC' },
            take: 30,
            relations: ['reviewer'],
          });

          if (reviews.length === 0) {
            subscriber.next({
              data: `No reviews yet for ${skillTitle || 'this skill'} ΓÇö once partners leave reviews, a digest appears here.`,
            } as MessageEvent);
            return;
          }

          const reviewsText = reviews
            .map((r) => {
              const stars =
                'Γÿà'.repeat(r.rating) + 'Γÿå'.repeat(Math.max(0, 5 - r.rating));
              const comment = r.comment?.trim() || '(no written comment)';
              return `[${stars}] ${comment}`;
            })
            .join('\n');

          const generator = this.aiService.streamSkillReviewsSummary(
            reviewsText,
            reviews.length,
            skillTitle || 'this skill',
          );
          for await (const chunk of generator) {
            subscriber.next({ data: chunk } as MessageEvent);
          }
        } catch (e) {
          subscriber.error(e);
        } finally {
          subscriber.next({ data: '[DONE]' } as MessageEvent);
          subscriber.complete();
        }
      })();
    });
  }

  @Public()
  @Sse('user/:id/reviews/summary/stream')
  streamUserReviewsSummary(
    @Param('id') userId: string,
  ): Observable<MessageEvent> {
    return new Observable<MessageEvent>((subscriber) => {
      (async () => {
        try {
          const reviews = await this.reviewRepository.find({
            where: { revieweeId: userId },
            order: { createdAt: 'DESC' },
            take: 30,
          });

          if (reviews.length === 0) {
            subscriber.next({
              data: 'No reviews yet ΓÇö once partners leave reviews, an AI digest appears here.',
            } as MessageEvent);
            return;
          }

          const reviewsText = reviews
            .map((r) => {
              const stars =
                'Γÿà'.repeat(r.rating) + 'Γÿå'.repeat(Math.max(0, 5 - r.rating));
              const comment = r.comment?.trim() || '(no written comment)';
              return `[${stars}] ${comment}`;
            })
            .join('\n');

          const generator = this.aiService.streamUserReviewsSummary(
            reviewsText,
            reviews.length,
          );
          for await (const chunk of generator) {
            subscriber.next({ data: chunk } as MessageEvent);
          }
        } catch (e) {
          subscriber.error(e);
        } finally {
          subscriber.next({ data: '[DONE]' } as MessageEvent);
          subscriber.complete();
        }
      })();
    });
  }

  private buildTranscript(messages: Message[]): string {
    return messages
      .map((m) => {
        const who = m.sender?.name?.trim() || `User ${m.senderId.slice(0, 4)}`;
        return `${who}: ${m.content}`;
      })
      .join('\n');
  }

  @Public()
  @Sse('session/:id/takeaways/stream')
  streamTakeaways(
    @Param('id') sessionId: string,
    @Query('notes') notes: string,
    @Req() req: any,
  ): Observable<MessageEvent> {
    return new Observable<MessageEvent>((subscriber) => {
      (async () => {
        try {
          const userId = req.user?.id || req.user?.sub;
          if (userId) {
            const sessionCheck = await this.sessionRepository.findOne({
              where: { id: sessionId },
              select: ['id', 'participant1Id', 'participant2Id'],
            });
            if (
              sessionCheck &&
              sessionCheck.participant1Id !== userId &&
              sessionCheck.participant2Id !== userId
            ) {
              subscriber.error(
                new UnauthorizedException(
                  'You are not a participant of this session',
                ),
              );
              return;
            }
          }

          if (!notes || notes.trim().length < 5) {
            subscriber.next({
              data: 'Please add a few more notes so the AI can generate meaningful takeaways.',
            } as MessageEvent);
            return;
          }

          const session = await this.sessionRepository.findOne({
            where: { id: sessionId },
            relations: ['skill1', 'skill2'],
          });

          if (!session) {
            subscriber.next({ data: 'Session not found.' } as MessageEvent);
            return;
          }

          const skillTitles = [
            session.skill1?.title,
            session.skill2?.title,
          ].filter(Boolean) as string[];

          const generator = this.aiService.streamTakeaways(notes, skillTitles);
          for await (const chunk of generator) {
            subscriber.next({ data: chunk } as MessageEvent);
          }
        } catch (e) {
          subscriber.error(e);
        } finally {
          subscriber.next({ data: '[DONE]' } as MessageEvent);
          subscriber.complete();
        }
      })();
    });
  }

  @Public()
  @Get('icebreaker')
  async getIcebreaker(
    @Query('wanted') wantedSkill: string,
    @Query('offered') offeredSkill: string,
    @Query('partner') partnerName: string,
  ): Promise<{ message: string }> {
    const message = await this.aiService.generateIcebreaker(
      wantedSkill || 'a new skill',
      offeredSkill || 'another skill',
      partnerName || 'partner',
    );
    return { message };
  }
}

import { createHash } from 'crypto';
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { GoogleGenerativeAI } from '@google/generative-ai';

// On a 429 we stop hitting the API for this long. Avoids burning the rest of the daily
// quota retrying when the key has `limit: 0` for everything we listed.
const QUOTA_COOLDOWN_MS = 10 * 60 * 1000;

@Injectable()
export class AiService {
  private readonly genAI: GoogleGenerativeAI;
  private readonly logger = new Logger(AiService.name);
  private readonly summaryModels: string[];
  private readonly hasApiKey: boolean;
  // In-process cache: summarising the same chat history twice in a row should not burn quota.
  private readonly summaryCache = new Map<string, string>();
  private static readonly SUMMARY_CACHE_LIMIT = 50;
  // Per-model cooldown ΓÇö a 429 on one model doesn't poison the others.
  private readonly modelCooldownUntil = new Map<string, number>();

  constructor(private readonly configService: ConfigService) {
    const apiKey =
      this.configService.get<string>('app.geminiApiKey') ??
      process.env.GEMINI_API_KEY;
    this.hasApiKey = Boolean(apiKey);
    if (!this.hasApiKey) {
      this.logger.warn(
        'Initialised without GEMINI_API_KEY. AI functions will return canned output.',
      );
    }
    this.genAI = new GoogleGenerativeAI(apiKey || 'DUMMY_KEY');

    const configuredModels =
      this.configService.get<string[]>('app.geminiSummaryModels') ?? [];
    this.summaryModels = configuredModels.length
      ? configuredModels
      : [
          'gemini-1.5-flash-latest',
          'gemini-1.5-pro-latest',
          'gemini-1.5-flash',
          'gemini-pro',
        ];
    this.logger.log(
      `Gemini summary fallback chain: ${this.summaryModels.join(' ΓåÆ ')}`,
    );
  }

  async generateEmbedding(text: string): Promise<number[]> {
    if (!this.hasApiKey) {
      return this.fallbackEmbedding();
    }
    const apiKey =
      this.configService.get<string>('app.geminiApiKey') ??
      process.env.GEMINI_API_KEY;
    if (!apiKey) return this.fallbackEmbedding();

    // Embedding models are only available under the v1beta endpoint (not v1).
    // gemini-embedding-001 is the stable replacement for the retired text-embedding-004.
    // gemini-embedding-2 is the newest available model (also on v1beta).
    // Both output 3072-dimensional vectors.
    const models = ['gemini-embedding-2', 'gemini-embedding-001'];
    for (const modelName of models) {
      try {
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:embedContent?key=${apiKey}`;
        const res = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            content: { parts: [{ text }] },
          }),
        });
        if (!res.ok) {
          const body = await res.text().catch(() => '');
          this.logger.warn(
            `Embedding HTTP ${res.status} for ${modelName}: ${body.substring(0, 200)}`,
          );
          continue;
        }
        const json = (await res.json()) as {
          embedding?: { values: number[] };
        };
        if (json?.embedding?.values) {
          return json.embedding.values;
        }
      } catch (err) {
        this.logger.warn(
          `Embedding failed for ${modelName}: ${(err as Error).message}`,
        );
      }
    }
    this.logger.warn(
      'All embedding API calls failed ΓÇö using random fallback vectors. ' +
        'Matching falls back to category-based similarity.',
    );
    return this.fallbackEmbedding();
  }

  private fallbackEmbedding(): number[] {
    // Must match the vector(3072) column dimension used by gemini-embedding-001.
    return Array.from({ length: 3072 }, () => Math.random() * 2 - 1);
  }

  async *streamSessionSummary(
    chatHistory: string,
  ): AsyncGenerator<string, void, unknown> {
    const prompt = [
      'You are summarising a skill-sharing session strictly from the literal chat transcript below.',
      '',
      'Hard rules:',
      '- Only summarise what is actually stated in the transcript. Never invent topics, skills, names, or next steps.',
      '- If the transcript is empty, contains only greetings/single characters/typos/test gibberish (e.g. "hi", "asas", "h", "df"), or has no concrete subject matter, respond with EXACTLY: "Not enough substantive chat to summarise yet ΓÇö keep teaching and try again later." and nothing else.',
      '- Do not name specific technologies, instruments, frameworks, or skills unless those exact words appear in the transcript.',
      '- Keep the tone warm and concise: 2 short paragraphs maximum.',
      '',
      'Transcript:',
      chatHistory,
    ].join('\n');
    yield* this.streamPrompt(prompt, chatHistory);
  }

  /**
   * Summarise the public reviews left for one user. The cache is keyed on the review payload
   * itself, so a new review naturally invalidates the entry (different SHA-1).
   */
  async *streamUserReviewsSummary(
    reviewsText: string,
    reviewCount: number,
  ): AsyncGenerator<string, void, unknown> {
    if (reviewCount < 2) {
      yield 'Not enough reviews yet to summarise ΓÇö at least 2 are needed for a meaningful overview.';
      return;
    }
    const prompt = [
      'You are writing a short reputation summary for a skill-exchange user, based ONLY on the verbatim reviews below.',
      '',
      'Hard rules:',
      '- Use only what reviewers actually wrote. Never invent strengths, weaknesses, skills, or anecdotes.',
      '- Surface recurring themes (e.g. patience, clarity, preparation) only if multiple reviews mention them.',
      '- If reviews are too sparse, vague, or contradictory to summarise, respond with EXACTLY: "Reviews are too sparse to draw a clear picture yet."',
      '- 1 short paragraph. Neutral and factual, not promotional. Do not invent a star rating.',
      '',
      `Reviews (${reviewCount} total):`,
      reviewsText,
    ].join('\n');
    yield* this.streamPrompt(prompt, `reviews:${reviewsText}`);
  }

  /**
   * Per-skill review summary. Same logic but scoped to one skill and includes the skill name.
   */
  async *streamSkillReviewsSummary(
    reviewsText: string,
    reviewCount: number,
    skillTitle: string,
  ): AsyncGenerator<string, void, unknown> {
    if (reviewCount < 1) {
      yield `No reviews yet for ${skillTitle}.`;
      return;
    }
    const prompt = [
      `You are writing a short skill-specific reputation summary for how someone teaches or exchanges "${skillTitle}", based ONLY on the verbatim reviews below.`,
      '',
      'Hard rules:',
      '- Use only what reviewers actually wrote. Never invent strengths, weaknesses, or anecdotes.',
      '- Focus specifically on the skill being discussed. Ignore mentions of other skills.',
      '- Surface recurring themes only if multiple reviews mention them.',
      '- If reviews are too sparse or vague to summarise, respond with EXACTLY: "Not enough reviews yet to draw a clear picture."',
      '- 1-2 short sentences. Neutral and factual.',
      '',
      `Reviews for ${skillTitle} (${reviewCount} total):`,
      reviewsText,
    ].join('\n');
    yield* this.streamPrompt(prompt, `skill:${skillTitle}:${reviewsText}`);
  }

  private async *streamPrompt(
    prompt: string,
    cacheSeed: string,
  ): AsyncGenerator<string, void, unknown> {
    const cacheKey = createHash('sha1').update(cacheSeed).digest('hex');
    const cached = this.summaryCache.get(cacheKey);
    if (cached) {
      yield cached;
      return;
    }

    if (!this.hasApiKey) {
      yield 'AI summaries are disabled ΓÇö no GEMINI_API_KEY is configured.';
      return;
    }

    let lastQuotaError = false;
    for (const modelName of this.summaryModels) {
      if (this.isCoolingDown(modelName)) {
        this.logger.debug(`Skipping ${modelName}: in 429 cooldown`);
        continue;
      }
      try {
        const model = this.genAI.getGenerativeModel({ model: modelName });
        const result = await model.generateContentStream(prompt);
        let full = '';
        try {
          for await (const chunk of result.stream) {
            const chunkText = chunk.text();
            full += chunkText;
            yield chunkText;
          }
        } catch (streamErr) {
          this.logger.error(
            `Stream iteration failed on ${modelName}`,
            streamErr,
          );
          // If we already have some content, yield it and return instead of failing the whole thing
          if (full) return;
          throw streamErr;
        }
        this.rememberSummary(cacheKey, full);
        return;
      } catch (err) {
        const message = (err as Error).message || '';
        const quotaHit =
          message.includes('429') || message.toLowerCase().includes('quota');
        if (quotaHit) {
          lastQuotaError = true;
          this.markCooldown(modelName);
          this.logger.warn(
            `Quota hit (429) on ${modelName}; cooling down for ${QUOTA_COOLDOWN_MS / 60000}m and trying next.`,
          );
          continue;
        }
        this.logger.error(`AI stream failed on ${modelName}`, err);
        // On any non-transient, non-quota error, we still try the next model in the chain
        // before giving up entirely.
        continue;
      }
    }

    if (!lastQuotaError) {
      this.logger.error(
        'AI entire fallback chain failed. This usually means the GEMINI_API_KEY is invalid, the region is restricted, or the models are unavailable.',
      );
    }

    yield lastQuotaError
      ? "Today's AI quota is fully used across all configured Gemini models. Try again later."
      : 'AI summary is temporarily unavailable. Check server logs for details.';
  }

  async *generateAgendaStream(
    offeredTitle: string,
    wantedTitle: string,
    durationMinutes: number,
  ): AsyncGenerator<string, void, unknown> {
    const prompt = [
      'You are creating a practical 3-step agenda for a 1-hour peer skill-exchange session.',
      `One person teaches "${offeredTitle}" and the other teaches "${wantedTitle}".`,
      `The session duration is ${durationMinutes} minutes.`,
      '',
      'Hard rules:',
      '- Produce exactly 3 time-boxed steps covering BOTH skills equally.',
      '- Include time allocations that add up to the session duration.',
      '- Each step should describe what both participants do.',
      '- Use markdown formatting with a brief intro and a short wrap-up note.',
      '- Do not invent prerequisites or assume prior experience.',
      '',
      'Example format:',
      '### Step 1: Foundations (0ΓÇô15 min)',
      '- Person A demonstrates core concepts of X',
      '- Person B asks questions and tries the first exercise',
      '',
      '### Step 2: ...',
      '',
      '### Step 3: ...',
      '',
      'Keep it concise, actionable, and realistic for a peer-to-peer session.',
    ].join('\n');
    yield* this.streamPrompt(
      prompt,
      `agenda:${offeredTitle}:${wantedTitle}:${durationMinutes}`,
    );
  }

  async generateLearningInsights(
    skillTitle: string,
    proficiencyLevel: string,
  ): Promise<{ roadmap: string; resources: any[] }> {
    const prompt = [
      `Career advisor for a user who completed "${skillTitle}" at ${proficiencyLevel} level.`,
      '',
      'Tasks:',
      '1. Short learning roadmap (3 stages, under 60 words).',
      '2. 2-3 high-quality free online resources (title, url, description).',
      '',
      'Respond ONLY with a JSON object:',
      '{ "roadmap": "markdown", "resources": [{ "title": "...", "url": "...", "description": "..." }] }',
      'No preamble.',
    ].join('\n');

    const response = await this.getSinglePromptResponse(
      prompt,
      `insights:${skillTitle}:${proficiencyLevel}`,
    );
    if (
      !response ||
      response.includes('error occurred') ||
      response.includes('unavailable')
    ) {
      return {
        roadmap: 'Roadmap generation is currently unavailable.',
        resources: [],
      };
    }

    try {
      const start = response.indexOf('{');
      const end = response.lastIndexOf('}');
      if (start === -1 || end === -1) throw new Error('No JSON object found');
      const json = JSON.parse(response.substring(start, end + 1));
      return {
        roadmap: json.roadmap || 'No roadmap generated.',
        resources: Array.isArray(json.resources) ? json.resources : [],
      };
    } catch (e) {
      this.logger.error(
        `Failed to parse AI insights JSON for ${skillTitle}`,
        e,
      );
      return { roadmap: 'Error parsing AI results.', resources: [] };
    }
  }

  async generateRoadmap(
    skillTitle: string,
    proficiencyLevel: string,
  ): Promise<string> {
    const insights = await this.generateLearningInsights(
      skillTitle,
      proficiencyLevel,
    );
    return insights.roadmap;
  }

  async generateResources(skillTitle: string): Promise<any[]> {
    const insights = await this.generateLearningInsights(
      skillTitle,
      'INTERMEDIATE',
    );
    return insights.resources;
  }

  async *streamTakeaways(
    rawNotes: string,
    skillTitles: string[],
  ): AsyncGenerator<string, void, unknown> {
    const prompt = [
      'You are a learning coach transforming rough post-session notes into polished takeaways.',
      '',
      `The session covered these skills: ${skillTitles.join(', ')}.`,
      '',
      'Transform the raw notes below into a clean, structured markdown summary with:',
      '- A brief 1-sentence overview of what was covered',
      '- Key learnings (bullet points)',
      '- Actionable next steps (numbered)',
      '- Resources or tools mentioned (if any)',
      '',
      'Keep it encouraging, concise, and practical. Do not invent skills or topics not implied by the notes.',
      'If the notes are too sparse (e.g. less than 10 words), respond with a gentle encouragement to add more detail next time.',
      '',
      'Raw notes:',
      rawNotes,
    ].join('\n');
    yield* this.streamPrompt(prompt, `takeaways:${rawNotes}`);
  }

  async generateIcebreaker(
    wantedSkill: string,
    offeredSkill: string,
    partnerName: string,
  ): Promise<string> {
    const prompt = [
      `Write a warm, 2-sentence opening message for a peer-to-peer skill exchange.`,
      `The sender wants to learn "${wantedSkill}" from ${partnerName}.`,
      `In return, they can teach "${offeredSkill}".`,
      '',
      'Tone: friendly, genuine, and enthusiastic ΓÇö not salesy or overly formal.',
      'Keep it under 60 words. Do not include greetings like "Hi" or "Hello" ΓÇö just the message body.',
    ].join('\n');
    return this.getSinglePromptResponse(
      prompt,
      `icebreaker:${wantedSkill}:${offeredSkill}:${partnerName}`,
    );
  }

  private async getSinglePromptResponse(
    prompt: string,
    cacheSeed: string,
  ): Promise<string> {
    const start = Date.now();
    const generator = this.streamPrompt(prompt, cacheSeed);
    let full = '';
    for await (const chunk of generator) {
      full += chunk;
    }
    this.logger.debug(
      `AI prompt [${cacheSeed.substring(0, 20)}...] took ${Date.now() - start}ms`,
    );
    return full;
  }

  private isCoolingDown(modelName: string): boolean {
    const until = this.modelCooldownUntil.get(modelName) ?? 0;
    return Date.now() < until;
  }

  private markCooldown(modelName: string) {
    this.modelCooldownUntil.set(modelName, Date.now() + QUOTA_COOLDOWN_MS);
  }

  private rememberSummary(key: string, value: string) {
    if (!value) return;
    if (this.summaryCache.size >= AiService.SUMMARY_CACHE_LIMIT) {
      const firstKey = this.summaryCache.keys().next().value;
      if (firstKey) this.summaryCache.delete(firstKey);
    }
    this.summaryCache.set(key, value);
  }
}

import { Resolver, Mutation, Args, Context } from '@nestjs/graphql';
import type { Response } from 'express';
import { AuthService } from './auth.service';
import { AuthResponse } from './dto/auth.response';
import { LoginInput } from './dto/login.input';
import { RegisterInput } from './dto/register.input';
import { Public } from '../../common/decorators/public.decorator';

@Resolver()
export class AuthResolver {
  constructor(private authService: AuthService) {}

  @Public()
  @Mutation(() => AuthResponse)
  async register(
    @Args('input') input: RegisterInput,
    @Context('res') res: Response,
  ): Promise<AuthResponse> {
    const { accessToken, user } = await this.authService.register(input);
    res.cookie('accessToken', accessToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 15 * 60 * 1000,
    });
    return { accessToken, user };
  }

  @Public()
  @Mutation(() => AuthResponse)
  async login(
    @Args('input') input: LoginInput,
    @Context('res') res: Response,
  ): Promise<AuthResponse> {
    const { accessToken, user } = await this.authService.login(input);
    res.cookie('accessToken', accessToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 15 * 60 * 1000,
    });
    return { accessToken, user };
  }

  @Public()
  @Mutation(() => AuthResponse)
  async guestLogin(@Context('res') res: Response): Promise<AuthResponse> {
    const { accessToken, user } = await this.authService.guestLogin();
    res.cookie('accessToken', accessToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 15 * 60 * 1000,
    });
    return { accessToken, user };
  }

  @Public()
  @Mutation(() => AuthResponse)
  async refreshToken(
    @Args('token') token: string,
    @Context('res') res: Response,
  ): Promise<AuthResponse> {
    const result = await this.authService.refreshToken(token);
    res.cookie('accessToken', result.accessToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 15 * 60 * 1000,
    });
    return result;
  }

  @Public()
  @Mutation(() => Boolean)
  async logout(@Context('res') res: Response): Promise<boolean> {
    if (res) {
      res.clearCookie('accessToken');
    }
    return true;
  }
}

import {
  Injectable,
  UnauthorizedException,
  BadRequestException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { ConfigService } from '@nestjs/config';
import * as bcrypt from 'bcryptjs';
import { User } from '../user/user.entity';
import { LoginInput } from './dto/login.input';
import { RegisterInput } from './dto/register.input';
import { AuthResponse } from './dto/auth.response';
import { JwtPayload } from './strategies/jwt.strategy';

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User)
    private userRepository: Repository<User>,
    private jwtService: JwtService,
    private configService: ConfigService,
  ) {}

  generateTokens(user: User): { accessToken: string; refreshToken?: string } {
    const payload: JwtPayload = { sub: user.id, email: user.email };
    const accessToken = this.jwtService.sign(payload, {
      secret: this.configService.get<string>('app.jwtSecret')!,
      expiresIn: this.configService.get<string>('app.jwtAccessExpiry') as any,
    });
    const refreshToken = this.jwtService.sign(payload, {
      secret: this.configService.get<string>('app.jwtRefreshSecret')!,
      expiresIn: this.configService.get<string>('app.jwtRefreshExpiry') as any,
    });
    return { accessToken, refreshToken };
  }

  async refreshToken(token: string): Promise<AuthResponse> {
    try {
      const payload = this.jwtService.verify<JwtPayload>(token, {
        secret: this.configService.get<string>('app.jwtRefreshSecret')!,
      });
      const user = await this.userRepository.findOne({
        where: { id: payload.sub },
      });
      if (!user) throw new UnauthorizedException('User not found');
      const { accessToken, refreshToken } = this.generateTokens(user);
      return { accessToken, refreshToken, user };
    } catch {
      throw new UnauthorizedException('Invalid or expired refresh token');
    }
  }

  async register(input: RegisterInput): Promise<AuthResponse> {
    const existingUser = await this.userRepository.findOne({
      where: { email: input.email },
    });
    if (existingUser) {
      throw new BadRequestException('User with this email already exists');
    }

    const salt = await bcrypt.genSalt(10);
    const passwordHash = await bcrypt.hash(input.password, salt);

    const user = this.userRepository.create({
      email: input.email,
      name: input.name,
      passwordHash,
    });
    await this.userRepository.save(user);

    const { accessToken } = this.generateTokens(user);
    return { accessToken, user };
  }

  async login(input: LoginInput): Promise<AuthResponse> {
    const user = await this.userRepository.findOne({
      where: { email: input.email },
    });
    if (!user || (!user.passwordHash && user.googleId)) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const isMatch = await bcrypt.compare(input.password, user.passwordHash!);
    if (!isMatch) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const { accessToken } = this.generateTokens(user);
    return { accessToken, user };
  }

  async guestLogin(): Promise<AuthResponse> {
    const guestId = Math.random().toString(36).substring(7);
    const user = this.userRepository.create({
      email: `guest_${guestId}@skillbridge.io`,
      name: `Guest User ${guestId}`,
      isGuest: true,
      isVerified: false,
    });
    await this.userRepository.save(user);

    const { accessToken, refreshToken } = this.generateTokens(user);
    return { accessToken, refreshToken, user };
  }

  async me(userId: string): Promise<User> {
    const user = await this.userRepository.findOne({ where: { id: userId } });
    if (!user) throw new UnauthorizedException('User not found');
    return user;
  }
}

import { PassportStrategy } from '@nestjs/passport';
import { Strategy, VerifyCallback } from 'passport-google-oauth20';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from '../../user/user.entity';

@Injectable()
export class GoogleStrategy extends PassportStrategy(Strategy, 'google') {
  constructor(
    configService: ConfigService,
    @InjectRepository(User)
    private userRepository: Repository<User>,
  ) {
    super({
      clientID: configService.get<string>('app.googleClientId') || 'client',
      clientSecret:
        configService.get<string>('app.googleClientSecret') || 'secret',
      callbackURL: configService.get<string>('app.googleCallbackUrl') || 'cb',
      scope: ['email', 'profile'],
    });
  }

  async validate(
    accessToken: string,
    refreshToken: string,
    profile: any,
    done: VerifyCallback,
  ): Promise<any> {
    const { id, emails, displayName, photos } = profile;
    const email = emails[0].value;
    const avatar = photos?.[0]?.value;

    let user = await this.userRepository.findOne({ where: { email } });

    if (!user) {
      user = this.userRepository.create({
        googleId: id,
        email,
        name: displayName,
        avatar,
        isVerified: true,
      });
      await this.userRepository.save(user);
    } else if (!user.googleId) {
      user.googleId = id;
      if (!user.avatar) user.avatar = avatar;
      await this.userRepository.save(user);
    }

    done(null, user);
  }
}

import { ExtractJwt, Strategy } from 'passport-jwt';
import { PassportStrategy } from '@nestjs/passport';
import { Injectable, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from '../../user/user.entity';

export interface JwtPayload {
  sub: string;
  email: string;
}

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(
    configService: ConfigService,
    @InjectRepository(User)
    private userRepository: Repository<User>,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        (req: any) => {
          if (!req || !req.headers) return null;
          return ExtractJwt.fromAuthHeaderAsBearerToken()(req);
        },
        (req: any) => {
          if (req && req.cookies) {
            return req.cookies['accessToken'];
          }
          return null;
        },
      ]),
      ignoreExpiration: false,
      secretOrKey: configService.get<string>('app.jwtSecret') || 'secret',
    });
  }

  async validate(payload: JwtPayload) {
    const user = await this.userRepository.findOne({
      where: { id: payload.sub },
    });
    if (!user) {
      throw new UnauthorizedException('User not found');
    }
    return user;
  }
}

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { GqlExecutionContext } from '@nestjs/graphql';
import { CacheService } from './cache.service';

@Injectable()
export class RateLimitGuard implements CanActivate {
  private readonly logger = new Logger(RateLimitGuard.name);
  private readonly LIMIT = 100;
  private readonly WINDOW_SECONDS = 60;

  constructor(private readonly cacheService: CacheService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    if (context.getType() === 'rpc') return true;

    let req;
    if (context.getType().toString() === 'graphql') {
      const gqlCtx = GqlExecutionContext.create(context).getContext();
      req = gqlCtx.req || gqlCtx; // Some setups put req directly in context, some nest it
    } else {
      req = context.switchToHttp().getRequest();
    }

    if (!req) {
      this.logger.warn('RateLimitGuard: No request object found in context');
      return true;
    }

    // In Express, req.ip or req.connection.remoteAddress exists
    const ip =
      req.ip ||
      req.headers?.['x-forwarded-for'] ||
      req.socket?.remoteAddress ||
      req.connection?.remoteAddress ||
      'unknown';

    // Extract userId if logged in, otherwise default to IP
    let identifier = ip;
    if (req.user?.id) {
      identifier = req.user.id;
    } else if (req.user?.sub) {
      identifier = req.user.sub;
    }

    const key = `ratelimit:${identifier}`;

    try {
      const redis = this.cacheService.client;
      const current = await redis.incr(key);

      if (current === 1) {
        await redis.expire(key, this.WINDOW_SECONDS);
      }

      if (current > this.LIMIT) {
        throw new HttpException(
          'Too many requests. Please try again later.',
          HttpStatus.TOO_MANY_REQUESTS,
        );
      }
      return true;
    } catch (err) {
      if (err instanceof HttpException) throw err;
      // Fail open if Redis is down
      return true;
    }
  }
}

