import {
  Resolver,
  Query,
  Mutation,
  Args,
  ResolveField,
  Parent,
  Int,
} from '@nestjs/graphql';
import { Inject } from '@nestjs/common';
import { PubSub } from 'graphql-subscriptions';
import { Message } from './message.entity';
import { MessageService } from './message.service';
import { CreateMessageInput } from './dto/create-message.input';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import { User } from '../user/user.entity';
import { DataloaderService } from '../dataloader/dataloader.service';

@Resolver(() => Message)
export class MessageResolver {
  constructor(
    private readonly messageService: MessageService,
    private readonly dataloaderService: DataloaderService,
    @Inject('PUB_SUB') private readonly pubSub: PubSub,
  ) {}

  @Query(() => [Message])
  async messages(
    @CurrentUser() user: any,
    @Args('sessionId') sessionId: string,
    @Args('limit', { type: () => Int, nullable: true })
    limit?: number,
    @Args('offset', { type: () => Int, nullable: true })
    offset?: number,
  ): Promise<Message[]> {
    return this.messageService.getMessagesBySession(
      sessionId,
      user.id || user.sub,
      limit,
      offset,
    );
  }

  @Mutation(() => Message)
  async sendMessage(
    @CurrentUser() user: any,
    @Args('input') input: CreateMessageInput,
  ): Promise<Message> {
    const message = await this.messageService.createMessage(
      user.id || user.sub,
      input,
    );
    this.pubSub.publish('messageAdded', { messageAdded: message });
    // Sending a message implicitly stops the "is typingΓÇª" indicator for this user.
    this.pubSub.publish('typingChanged', {
      typingChanged: {
        sessionId: input.sessionId,
        userId: user.id || user.sub,
        userName: user.name,
        isTyping: false,
      },
    });
    return message;
  }

  @Mutation(() => Boolean)
  async setTyping(
    @CurrentUser() user: any,
    @Args('sessionId') sessionId: string,
    @Args('isTyping') isTyping: boolean,
  ): Promise<boolean> {
    this.pubSub.publish('typingChanged', {
      typingChanged: {
        sessionId,
        userId: user.id || user.sub,
        userName: user.name,
        isTyping,
      },
    });
    return true;
  }

  @Mutation(() => Int)
  async markSessionRead(
    @CurrentUser() user: any,
    @Args('sessionId') sessionId: string,
  ): Promise<number> {
    return this.messageService.markSessionRead(sessionId, user.id || user.sub);
  }

  @ResolveField(() => User, { nullable: true })
  async sender(@Parent() message: Message): Promise<User | null> {
    if (!message.senderId) return null;
    return this.dataloaderService.userLoader.load(message.senderId);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { RabbitSubscribe } from '@golevelup/nestjs-rabbitmq';
import { NotificationService } from './notification.service';
import { NotificationType } from './notification.entity';

@Injectable()
export class NotificationConsumer {
  private readonly logger = new Logger(NotificationConsumer.name);

  constructor(private readonly notificationService: NotificationService) {}

  @RabbitSubscribe({
    exchange: 'skillbridge.exchange',
    routingKey: 'notification.send',
    queue: 'notification-email-queue',
  })
  public async handleSendNotification(msg: any) {
    this.logger.log(
      `Received notification request for user ${msg.userId}: ${msg.title}`,
    );

    // Save the notification which acts as the in-app notification publisher
    await this.notificationService.create({
      userId: msg.userId,
      type: msg.type || NotificationType.MATCH_REQUEST,
      title: msg.title,
      message: msg.message,
      relatedId: msg.relatedId,
    });

    // Future expansion: Send the actual email notification through Sendgrid/Resend!
  }
}

import { Resolver, Query, Mutation, Args, Subscription } from '@nestjs/graphql';
import { Inject } from '@nestjs/common';
import { Notification } from './notification.entity';
import { NotificationService } from './notification.service';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import { PubSub } from 'graphql-subscriptions';

@Resolver(() => Notification)
export class NotificationResolver {
  constructor(
    private readonly notificationService: NotificationService,
    @Inject('PUB_SUB') private pubSub: PubSub,
  ) {}

  @Query(() => [Notification])
  async myNotifications(@CurrentUser() user: any): Promise<Notification[]> {
    return this.notificationService.findMyNotifications(user.id || user.sub);
  }

  @Mutation(() => Notification)
  async markNotificationRead(
    @CurrentUser() user: any,
    @Args('id') id: string,
  ): Promise<Notification> {
    return this.notificationService.markAsRead(id, user.id || user.sub);
  }

  @Subscription(() => Notification, {
    filter: (payload, variables) => {
      // payload data structure from PubSub publish: payload.onNotification
      return payload.onNotification.userId === variables.userId;
    },
  })
  onNotification(@Args('userId') userId: string) {
    // Note: We use dynamic subscription tags to scale across different user streams efficiently.
    return this.pubSub.asyncIterableIterator(`notificationData_${userId}`);
  }
}

import { Injectable, Inject, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Notification } from './notification.entity';
import { CreateNotificationInput } from './dto/create-notification.input';
import { PubSub } from 'graphql-subscriptions';

@Injectable()
export class NotificationService {
  constructor(
    @InjectRepository(Notification)
    private notificationRepository: Repository<Notification>,
    @Inject('PUB_SUB') private readonly pubSub: PubSub,
  ) {}

  async create(input: CreateNotificationInput): Promise<Notification> {
    const notification = this.notificationRepository.create(input);
    const saved = await this.notificationRepository.save(notification);

    // Publish via GraphQL subscriptions to frontends listening
    this.pubSub.publish(`notificationData_${saved.userId}`, {
      onNotification: saved,
    });

    return saved;
  }

  async findMyNotifications(userId: string): Promise<Notification[]> {
    return this.notificationRepository.find({
      where: { userId },
      order: { createdAt: 'DESC' },
    });
  }

  async markAsRead(id: string, userId: string): Promise<Notification> {
    const notif = await this.notificationRepository.findOne({
      where: { id, userId },
    });
    if (!notif) throw new NotFoundException('Notification not found');
    notif.isRead = true;
    return this.notificationRepository.save(notif);
  }
}

