      await service.autoCancelStaleSessions();
      expect(sessionRepo.save).not.toHaveBeenCalled();
    });

    it('cancels sessions older than 14 days in NEGOTIATING status', async () => {
      const stale = makeSession({
        status: SessionStatus.NEGOTIATING,
        updatedAt: new Date(Date.now() - 15 * 24 * 60 * 60 * 1000),
      });
      stale.participant1 = { id: mockUserId, name: 'User1' } as User;
      stale.participant2 = { id: mockPartnerId, name: 'User2' } as User;
      sessionRepo.find.mockResolvedValue([stale]);
      sessionRepo.save.mockResolvedValue({
        ...stale,
        status: SessionStatus.CANCELLED,
      });

      await service.autoCancelStaleSessions();

      expect(sessionRepo.save).toHaveBeenCalled();
      expect(stale.status).toBe(SessionStatus.CANCELLED);
      expect(stale.summary).toBe(
        'Auto-cancelled: session inactive for 14 days.',
      );
      expect(notificationService.create).toHaveBeenCalledTimes(2);
    });

    it('handles missing participant names gracefully', async () => {
      const stale = makeSession({
        status: SessionStatus.NEGOTIATING,
        updatedAt: new Date(Date.now() - 15 * 24 * 60 * 60 * 1000),
      });
      stale.participant1 = { id: mockUserId } as User;
      stale.participant2 = { id: mockPartnerId } as User;
      sessionRepo.find.mockResolvedValue([stale]);
      sessionRepo.save.mockResolvedValue(stale);

      await service.autoCancelStaleSessions();
      expect(notificationService.create).toHaveBeenCalled();
    });

    it('continues processing other sessions when notification fails', async () => {
      const stale1 = makeSession({
        id: 's1',
        status: SessionStatus.NEGOTIATING,
        updatedAt: new Date(Date.now() - 15 * 24 * 60 * 60 * 1000),
      });
      stale1.participant1 = { id: mockUserId } as User;
      stale1.participant2 = { id: mockPartnerId } as User;
      const stale2 = makeSession({
        id: 's2',
        status: SessionStatus.NEGOTIATING,
        updatedAt: new Date(Date.now() - 16 * 24 * 60 * 60 * 1000),
      });
      stale2.participant1 = { id: 'u3' } as User;
      stale2.participant2 = { id: 'u4' } as User;

      // Both notifications for stale1 are in ONE try/catch, so if the first fails,
      // the second is skipped. stale2's two notifications should still fire.
      notificationService.create.mockRejectedValueOnce(new Error('db error'));

      sessionRepo.find.mockResolvedValue([stale1, stale2]);
      sessionRepo.save.mockResolvedValue(stale1);

      await service.autoCancelStaleSessions();

      expect(notificationService.create).toHaveBeenCalledTimes(3);
    });
  });
});

import {
  Injectable,
  NotFoundException,
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Logger,
  OnApplicationBootstrap,
  Inject,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DataSource, Repository, LessThan } from 'typeorm';
import { Cron, CronExpression } from '@nestjs/schedule';
import { PubSub } from 'graphql-subscriptions';
import { Session, SessionStatus } from './session.entity';
import { UpdateSessionInput } from './dto/update-session.input';
import {
  MatchRequest,
  MatchRequestStatus,
} from '../match/match-request.entity';
import { User } from '../user/user.entity';
import { AiService } from '../ai/ai.service';
import { Skill } from '../skill/skill.entity';
import { NotificationService } from '../notification/notification.service';
import { NotificationType } from '../notification/notification.entity';

@Injectable()
export class SessionService implements OnApplicationBootstrap {
  private readonly logger = new Logger(SessionService.name);

  constructor(
    @InjectRepository(Session)
    private sessionRepository: Repository<Session>,
    @InjectRepository(MatchRequest)
    private matchRequestRepository: Repository<MatchRequest>,
    @InjectRepository(Skill)
    private skillRepository: Repository<Skill>,
    @InjectRepository(User)
    private userRepository: Repository<User>,
    @Inject('PUB_SUB') private readonly pubSub: PubSub,
    private readonly aiService: AiService,
    private readonly notificationService: NotificationService,
    private readonly dataSource: DataSource,
  ) {}

  private async saveAndBroadcast(session: Session): Promise<Session> {
    const saved = await this.sessionRepository.save(session);
    this.pubSub.publish('sessionUpdated', { sessionUpdated: saved });
    return saved;
  }

  /**
   * Backfill: for any ACCEPTED match request that doesn't have a session yet (for example
   * because RabbitMQ wasn't running when it was accepted), create one. Runs once on boot.
   */
  async onApplicationBootstrap(): Promise<void> {
    try {
      const orphans = await this.matchRequestRepository
        .createQueryBuilder('mr')
        .leftJoin(Session, 's', 's.matchRequestId = mr.id')
        .where('mr.status = :status', { status: MatchRequestStatus.ACCEPTED })
        .andWhere('s.id IS NULL')
        .getMany();

      if (orphans.length === 0) return;

      this.logger.log(
        `Backfilling ${orphans.length} session(s) for already-accepted match requestsΓÇª`,
      );

      for (const mr of orphans) {
        const session = this.sessionRepository.create({
          matchRequestId: mr.id,
          participant1Id: mr.fromUserId,
          participant2Id: mr.toUserId,
          skill1Id: mr.offeredSkillId,
          skill2Id: mr.wantedSkillId,
          status: SessionStatus.NEGOTIATING,
        });
        await this.sessionRepository.save(session);
      }
    } catch (err) {
      this.logger.warn(`Session backfill skipped: ${(err as Error).message}`);
    }
  }

  private async assertNotGuest(userId: string): Promise<void> {
    const user = await this.userRepository.findOne({
      where: { id: userId },
      select: ['isGuest'],
    });
    if (user?.isGuest) {
      throw new ForbiddenException(
        'Guest accounts cannot perform this action. Please register first.',
      );
    }
  }

  async createSessionFromMatch(
    matchRequestId: string,
    participant1Id: string,
    participant2Id: string,
    skill1Id: string,
    skill2Id: string,
  ): Promise<Session> {
    const session = this.sessionRepository.create({
      matchRequestId,
      participant1Id,
      participant2Id,
      skill1Id,
      skill2Id,
      status: SessionStatus.NEGOTIATING,
    });
    return this.saveAndBroadcast(session);
  }

  async getSession(userId: string, sessionId: string): Promise<Session> {
    const session = await this.sessionRepository.findOne({
      where: { id: sessionId },
    });
    if (!session) throw new NotFoundException('Session not found');

    if (
      session.participant1Id !== userId &&
      session.participant2Id !== userId
    ) {
      throw new BadRequestException('You do not have access to this session');
    }
    return session;
  }

  async getMySessions(userId: string): Promise<Session[]> {
    return this.sessionRepository.find({
      where: [{ participant1Id: userId }, { participant2Id: userId }],
      order: { createdAt: 'DESC' },
    });
  }

  /**
   * Updating scheduling details. Once scheduledAt + format are set, NEGOTIATING auto-promotes to SCHEDULED.
   */
  async updateSessionDetails(
    userId: string,
    sessionId: string,
    input: UpdateSessionInput,
  ): Promise<Session> {
    await this.assertNotGuest(userId);
    const session = await this.getSession(userId, sessionId);

    if (session.version !== input.version) {
      throw new ConflictException(
        'Session was updated by your partner. Please refresh.',
      );
    }

    if (
      session.status === SessionStatus.ACTIVE ||
      session.status === SessionStatus.COMPLETED ||
      session.status === SessionStatus.REVIEWED
    ) {
      throw new BadRequestException(
        'Logistics cannot be changed once the session has started.',
      );
    }

    // CON-1: Double-booking prevention ΓÇö if scheduledAt changes, ensure neither participant
    // has another SCHEDULED or ACTIVE session within +/- 60 minutes.
    if (input.scheduledAt) {
      const proposedTime = new Date(input.scheduledAt);
      const windowStart = new Date(proposedTime.getTime() - 60 * 60 * 1000);
      const windowEnd = new Date(proposedTime.getTime() + 60 * 60 * 1000);

      const conflicting = await this.sessionRepository
        .createQueryBuilder('s')
        .where(
          '(s.participant1Id = :p1 OR s.participant2Id = :p1 OR s.participant1Id = :p2 OR s.participant2Id = :p2)',
          { p1: session.participant1Id, p2: session.participant2Id },
        )
        .andWhere('s.id != :currentId', { currentId: sessionId })
        .andWhere('s.status IN (:...statuses)', {
          statuses: [SessionStatus.SCHEDULED, SessionStatus.ACTIVE],
        })
        .andWhere('s."scheduledAt" IS NOT NULL')
        .andWhere('s."scheduledAt" BETWEEN :start AND :end', {
          start: windowStart,
          end: windowEnd,
        })
        .getOne();

      if (conflicting) {
        throw new ConflictException('Time slot is double-booked');
      }
    }

    const wasNegotiating = session.status === SessionStatus.NEGOTIATING;
    Object.assign(session, input);

    if (
      session.status === SessionStatus.NEGOTIATING &&
      session.scheduledAt &&
      session.format
    ) {
      session.status = SessionStatus.SCHEDULED;
    }

    const saved = await this.saveAndBroadcast(session);

    const partnerId =
      session.participant1Id === userId
        ? session.participant2Id
        : session.participant1Id;

    if (input.scheduledAt || input.format) {
      await this.notificationService.create({
        userId: partnerId,
        type: NotificationType.MATCH_ACCEPTED,
        title: 'Session Updated',
        message: 'Your partner updated the session logistics.',
        relatedId: sessionId,
      });
    } else if (wasNegotiating && session.status === SessionStatus.SCHEDULED) {
      await this.notificationService.create({
        userId: partnerId,
        type: NotificationType.MATCH_ACCEPTED,
        title: 'Session Scheduled',
        message: `Your session is now ${SessionStatus.SCHEDULED}.`,
        relatedId: sessionId,
      });
    }

    return saved;
  }

  async advanceSessionStatus(
    userId: string,
    sessionId: string,
    targetStatus: SessionStatus,
  ): Promise<Session> {
    await this.assertNotGuest(userId);
    const session = await this.getSession(userId, sessionId);

    const allowed: Record<SessionStatus, SessionStatus[]> = {
      [SessionStatus.NEGOTIATING]: [
        SessionStatus.SCHEDULED,
        SessionStatus.ACTIVE,
        SessionStatus.CANCELLED,
      ],
      [SessionStatus.SCHEDULED]: [
        SessionStatus.ACTIVE,
        SessionStatus.NEGOTIATING,
        SessionStatus.CANCELLED,
      ],
      [SessionStatus.ACTIVE]: [
        SessionStatus.COMPLETED,
        SessionStatus.CANCELLED,
      ],
      [SessionStatus.COMPLETED]: [SessionStatus.REVIEWED],
      [SessionStatus.REVIEWED]: [],
      [SessionStatus.CANCELLED]: [],
    };

    if (!allowed[session.status]?.includes(targetStatus)) {
      throw new BadRequestException(
        `Cannot transition session from ${session.status} to ${targetStatus}.`,
      );
    }

    if (targetStatus === SessionStatus.ACTIVE && !session.scheduledAt) {
      session.scheduledAt = new Date();
    }

    const result = await this.dataSource.query(
      `UPDATE sessions SET status = $1, "version" = "version" + 1 WHERE id = $2 AND "version" = $3`,
      [targetStatus, sessionId, session.version],
    );

    const affected =
      typeof result?.[1] === 'number'
        ? result[1]
        : ((result?.rowCount as number | undefined) ?? 0);

    if (affected === 0) {
      throw new ConflictException(
        'Session was updated by your partner. Please refresh.',
      );
    }

    const updated = await this.sessionRepository.findOne({
      where: { id: sessionId },
    });
    if (!updated) throw new NotFoundException('Session not found');
    this.pubSub.publish('sessionUpdated', { sessionUpdated: updated });

    const partnerId =
      updated.participant1Id === userId
        ? updated.participant2Id
        : updated.participant1Id;

    const notifType =
      targetStatus === SessionStatus.CANCELLED
        ? NotificationType.SESSION_CANCELLED
        : targetStatus === SessionStatus.ACTIVE
          ? NotificationType.SESSION_REMINDER
          : NotificationType.SESSION_COMPLETED;

    await this.notificationService.create({
      userId: partnerId,
      type: notifType,
      title: 'Status Changed',
      message: `Your session is now ${targetStatus}.`,
      relatedId: sessionId,
    });

    return updated;
  }

  /**
   * Each participant can flip their own "I taught my part" flag. When both are done, the
   * session auto-promotes from ACTIVE ΓåÆ COMPLETED so reviews can unlock.
   * Uses atomic SQL toggles to prevent race conditions when both users toggle simultaneously.
   */
  async toggleSessionProgress(
    userId: string,
    sessionId: string,
  ): Promise<Session> {
    await this.assertNotGuest(userId);
    const session = await this.getSession(userId, sessionId);

    if (
      session.status !== SessionStatus.ACTIVE &&
      session.status !== SessionStatus.SCHEDULED
    ) {
      throw new BadRequestException(
        'Session must be scheduled or active to mark progress.',
      );
    }

    // Atomic toggle: flip the boolean and bump version in one SQL statement.
    const field =
      session.participant1Id === userId ? 'p1Completed' : 'p2Completed';
    const result = await this.dataSource.query(
      `UPDATE sessions SET "${field}" = NOT "${field}", "version" = "version" + 1 WHERE id = $1 AND "version" = $2`,
      [sessionId, session.version],
    );

    const affected =
      typeof result?.[1] === 'number'
        ? result[1]
        : ((result?.rowCount as number | undefined) ?? 0);

    if (affected === 0) {
      throw new ConflictException(
        'Session was updated by your partner. Please refresh.',
      );
    }

    // Re-read fresh state
    const updated = await this.sessionRepository.findOne({
      where: { id: sessionId },
    });
    if (!updated) throw new NotFoundException('Session not found');

    const partnerId =
      updated.participant1Id === userId
        ? updated.participant2Id
        : updated.participant1Id;

    if (updated.p1Completed && updated.p2Completed) {
      updated.status = SessionStatus.COMPLETED;
      await this.dataSource.query(
        'UPDATE skills SET "swappedCount" = "swappedCount" + 1 WHERE id IN ($1, $2)',
        [updated.skill1Id, updated.skill2Id],
      );
      this.generatePostSessionInsights(updated.id).catch((err) =>
        this.logger.error(
          `Failed to generate insights for session ${updated.id}`,
          err,
        ),
      );
      await this.saveAndBroadcast(updated);
      for (const uid of [updated.participant1Id, updated.participant2Id]) {
        await this.notificationService.create({
          userId: uid,
          type: NotificationType.SESSION_COMPLETED,
          title: 'Session Completed',
          message: `Your session is now COMPLETED.`,
          relatedId: sessionId,
        });
      }
    } else if (updated.status === SessionStatus.SCHEDULED) {
      updated.status = SessionStatus.ACTIVE;
      await this.saveAndBroadcast(updated);
      await this.notificationService.create({
        userId: partnerId,
        type: NotificationType.SESSION_REMINDER,
        title: 'Session Active',
        message:
          'Your partner marked their part complete. Session is now ACTIVE.',
        relatedId: sessionId,
      });
    } else {
      await this.saveAndBroadcast(updated);
      const myCompletion =
        updated.participant1Id === userId
          ? updated.p1Completed
          : updated.p2Completed;
      await this.notificationService.create({
        userId: partnerId,
        type: NotificationType.MATCH_ACCEPTED,
        title: 'Progress Update',
        message: myCompletion
          ? 'Your partner marked their part complete.'
          : 'Your partner undone their completion.',
        relatedId: sessionId,
      });
    }

    return updated;
  }

  async cancelSession(
    userId: string,
    sessionId: string,
    reason: string,
  ): Promise<Session> {
    await this.assertNotGuest(userId);
    const session = await this.getSession(userId, sessionId);

    if (
      session.status !== SessionStatus.NEGOTIATING &&
      session.status !== SessionStatus.SCHEDULED
    ) {
      throw new BadRequestException(
        'Only negotiating or scheduled sessions can be cancelled.',
      );
    }

    const result = await this.dataSource.query(
      `UPDATE sessions SET status = $1, summary = $2, "version" = "version" + 1 WHERE id = $3 AND "version" = $4`,
      [
        SessionStatus.CANCELLED,
        reason || 'Session cancelled by user.',
        sessionId,
        session.version,
      ],
    );

    const affected =
      typeof result?.[1] === 'number'
        ? result[1]
        : ((result?.rowCount as number | undefined) ?? 0);

    if (affected === 0) {
      throw new ConflictException(
        'Session was updated by your partner. Please refresh.',
      );
    }

    const updated = await this.sessionRepository.findOne({
      where: { id: sessionId },
    });
    if (!updated) throw new NotFoundException('Session not found');
    this.pubSub.publish('sessionUpdated', { sessionUpdated: updated });

    const partnerId =
      updated.participant1Id === userId
        ? updated.participant2Id
        : updated.participant1Id;
    await this.notificationService.create({
      userId: partnerId,
      type: NotificationType.SESSION_CANCELLED,
      title: 'Session Cancelled',
      message: reason || 'Your partner cancelled the session.',
      relatedId: sessionId,
    });

    return updated;
  }

  /**
   * Cron job: runs every day at midnight to auto-cancel stale negotiating sessions.
   * Sessions stuck in NEGOTIATING for more than 14 days are cancelled and both parties notified.
   */
  @Cron(CronExpression.EVERY_DAY_AT_MIDNIGHT)
  async autoCancelStaleSessions(): Promise<void> {
    const fourteenDaysAgo = new Date();
    fourteenDaysAgo.setDate(fourteenDaysAgo.getDate() - 14);

    const staleSessions = await this.sessionRepository.find({
      where: {
        status: SessionStatus.NEGOTIATING,
        updatedAt: LessThan(fourteenDaysAgo),
      },
      relations: ['participant1', 'participant2'],
    });

    if (staleSessions.length === 0) return;

    this.logger.log(
      `Auto-cancelling ${staleSessions.length} stale negotiating sessions`,
    );

    for (const session of staleSessions) {
      session.status = SessionStatus.CANCELLED;
      session.summary = 'Auto-cancelled: session inactive for 14 days.';
      await this.sessionRepository.save(session);

      try {
        await this.notificationService.create({
          userId: session.participant1Id,
          type: NotificationType.SESSION_COMPLETED,
          title: 'Session expired',
          message: `Your session with ${session.participant2?.name ?? 'your partner'} was auto-cancelled after 14 days of inactivity.`,
          relatedId: session.id,
        });

        await this.notificationService.create({
          userId: session.participant2Id,
          type: NotificationType.SESSION_COMPLETED,
          title: 'Session expired',
          message: `Your session with ${session.participant1?.name ?? 'your partner'} was auto-cancelled after 14 days of inactivity.`,
          relatedId: session.id,
        });
      } catch (err) {
        this.logger.error(
          `Failed to send expiration notifications for session ${session.id}`,
          err,
        );
      }
    }
  }

  private async generatePostSessionInsights(sessionId: string): Promise<void> {
    const session = await this.sessionRepository.findOne({
      where: { id: sessionId },
      relations: ['skill1', 'skill2'],
    });
    if (!session || !session.skill1 || !session.skill2) return;

    this.logger.log(
      `Starting AI insight generation for session ${sessionId}...`,
    );
    const start = Date.now();
    const [insights1, insights2] = await Promise.all([
      this.aiService.generateLearningInsights(
        session.skill1.title,
        session.skill1.proficiencyLevel || 'INTERMEDIATE',
      ),
      this.aiService.generateLearningInsights(
        session.skill2.title,
        session.skill2.proficiencyLevel || 'INTERMEDIATE',
      ),
    ]);

    const roadmap = `### For ${session.skill1.title}:\n${insights1.roadmap}\n\n### For ${session.skill2.title}:\n${insights2.roadmap}`;
    const suggestedResources = {
      [session.skill1.title]: insights1.resources,
      [session.skill2.title]: insights2.resources,
    };

    // Direct UPDATE bypassing version lock since AI generation is async
    // and the session may have been modified by other operations.
    await this.dataSource.query(
      `UPDATE sessions SET "roadmap" = $1, "suggestedResources" = $2 WHERE id = $3`,
      [roadmap, JSON.stringify(suggestedResources), sessionId],
    );

    this.pubSub.publish('sessionUpdated', {
      sessionUpdated: await this.sessionRepository.findOne({
        where: { id: sessionId },
      }),
    });

    this.logger.log(
      `Finished AI insights for ${sessionId} in ${Date.now() - start}ms.`,
    );
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
  ForbiddenException,
  OnApplicationBootstrap,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { IsNull, Repository, In } from 'typeorm';
import { Skill, SkillType } from './skill.entity';
import { Portfolio } from './portfolio.entity';
import { User } from '../user/user.entity';
import { CreateSkillInput } from './dto/create-skill.input';
import { UpdateSkillInput } from './dto/update-skill.input';
import { UpdatePortfolioInput } from './dto/update-portfolio.input';
import { CursorPaginationInput } from '../../common/dto/cursor-pagination.input';
import { PaginatedSkills, SkillEdge } from './dto/paginated-skills.output';
import { AddPortfolioInput } from './dto/add-portfolio.input';
import { AiService } from '../ai/ai.service';

@Injectable()
export class SkillService implements OnApplicationBootstrap {
  private readonly logger = new Logger(SkillService.name);

  constructor(
    @InjectRepository(Skill)
    private skillRepository: Repository<Skill>,
    @InjectRepository(Portfolio)
    private portfolioRepository: Repository<Portfolio>,
    @InjectRepository(User)
    private userRepository: Repository<User>,
    private readonly aiService: AiService,
  ) {}

  /**
   * Backfill embeddings for any skill rows that are missing them. Runs once on boot, low
   * concurrency so we don't blow through the Gemini free quota in a burst. Skipped silently
   * when the API isn't reachable ΓÇö the recommender falls back to category match.
   */
  async onApplicationBootstrap(): Promise<void> {
    try {
      const orphans = await this.skillRepository.find({
        where: { embedding: IsNull(), isActive: true },
        take: 50,
      });
      if (orphans.length === 0) return;
      this.logger.log(`Backfilling embeddings for ${orphans.length} skill(s)ΓÇª`);
      for (const skill of orphans) {
        try {
          const embedding = await this.aiService.generateEmbedding(
            this.embeddableText(skill),
          );
          if (embedding) {
            skill.embedding = embedding;
            await this.skillRepository.save(skill);
          }
        } catch (err) {
          this.logger.warn(
            `Embedding skipped for skill ${skill.id}: ${(err as Error).message}`,
          );
        }
      }
    } catch (err) {
      this.logger.warn(`Embedding backfill skipped: ${(err as Error).message}`);
    }
  }

  private embeddableText(skill: {
    title: string;
    description?: string | null;
    category?: string | null;
  }): string {
    return [skill.title, skill.category, skill.description]
      .filter(Boolean)
      .join(' ΓÇö ');
  }

  private async attachEmbedding(skill: Skill): Promise<void> {
    try {
      const embedding = await this.aiService.generateEmbedding(
        this.embeddableText(skill),
      );
      if (embedding) {
        skill.embedding = embedding;
      }
    } catch (err) {
      this.logger.warn(`Could not embed skill: ${(err as Error).message}`);
    }
  }

  private async assertNotGuest(userId: string): Promise<void> {
    const user = await this.userRepository.findOne({
      where: { id: userId },
      select: ['isGuest'],
    });
    if (user?.isGuest) {
      throw new ForbiddenException(
        'Guest accounts cannot perform this action. Please register first.',
      );
    }
  }

  async createSkill(userId: string, input: CreateSkillInput): Promise<Skill> {
    await this.assertNotGuest(userId);
    const skill = this.skillRepository.create({
      ...input,
      userId,
    });
    await this.attachEmbedding(skill);
    return this.skillRepository.save(skill);
  }

  async updateSkill(
    userId: string,
    id: string,
    input: UpdateSkillInput,
  ): Promise<Skill> {
    await this.assertNotGuest(userId);
    const skill = await this.skillRepository.findOne({ where: { id, userId } });
    if (!skill)
      throw new NotFoundException(
        'Skill not found or you do not have permission.',
      );

    const titleChanged =
      input.title !== undefined && input.title !== skill.title;
    const descChanged =
      input.description !== undefined &&
      input.description !== skill.description;
    const categoryChanged =
      input.category !== undefined && input.category !== skill.category;

    Object.assign(skill, input);

    // Re-embed only when the semantic content actually changed.
    if (titleChanged || descChanged || categoryChanged) {
      await this.attachEmbedding(skill);
    }

    return this.skillRepository.save(skill);
  }

  async toggleSkillActive(userId: string, id: string): Promise<Skill> {
    await this.assertNotGuest(userId);
    const skill = await this.skillRepository.findOne({ where: { id, userId } });
    if (!skill)
      throw new NotFoundException(
        'Skill not found or you do not have permission.',
      );

    skill.isActive = !skill.isActive;
    return this.skillRepository.save(skill);
  }

  async deleteSkill(userId: string, id: string): Promise<boolean> {
    await this.assertNotGuest(userId);
    const skill = await this.skillRepository.findOne({ where: { id, userId } });
    if (!skill)
      throw new NotFoundException(
        'Skill not found or you do not have permission.',
      );

    // Prevent deletion if the skill is in any active exchange
    const activeRequestCount = await this.skillRepository.manager.query(
      `SELECT COUNT(*)::int AS count FROM match_requests
       WHERE ("offeredSkillId" = $1 OR "wantedSkillId" = $1)
         AND status = 'PENDING'`,
      [id],
    );

    const activeSessionCount = await this.skillRepository.manager.query(
      `SELECT COUNT(*)::int AS count FROM sessions
       WHERE ("skill1Id" = $1 OR "skill2Id" = $1)
         AND status IN ('NEGOTIATING', 'SCHEDULED', 'ACTIVE')`,
      [id],
    );

    if (
      (activeRequestCount[0]?.count ?? 0) > 0 ||
      (activeSessionCount[0]?.count ?? 0) > 0
    ) {
      throw new BadRequestException(
        'Cannot delete a skill that is part of an active exchange. Deactivate it instead.',
      );
    }

    await this.skillRepository.remove(skill);
    return true;
  }

  async mySkills(userId: string): Promise<Skill[]> {
    return this.skillRepository.find({
      where: { userId },
      order: { createdAt: 'DESC' },
    });
  }

  async findSkillsByUserId(userId: string): Promise<Skill[]> {
    return this.skillRepository.find({
      where: { userId },
      order: { createdAt: 'DESC' },
    });
  }

  async searchSkills(
    currentUserId: string,
    query?: string,
    category?: string,
    type?: string,
    pagination: CursorPaginationInput = { limit: 20 },
  ): Promise<PaginatedSkills> {
    const qb = this.skillRepository
      .createQueryBuilder('skill')
      .leftJoinAndSelect('skill.user', 'user')
      .where('skill.isActive = :active', { active: true })
      .andWhere('skill.userId != :uid', { uid: currentUserId });

    if (query && query.trim()) {
      qb.andWhere(
        '(LOWER(skill.title) LIKE :q OR LOWER(skill.description) LIKE :q)',
        { q: `%${query.toLowerCase()}%` },
      );
    }

    if (category && category !== 'All') {
      qb.andWhere('skill.category = :category', { category });
    }

    if (type && (type === SkillType.OFFER || type === SkillType.WANT)) {
      qb.andWhere('skill.type = :type', { type });
    }

    // Cursor-based: fetch one extra to determine if there's a next page.
    const limit = pagination.limit + 1;

    if (pagination.cursor) {
      const cursorDate = new Date(
        Buffer.from(pagination.cursor, 'base64').toString('utf-8'),
      );
      qb.andWhere('skill."createdAt" < :cursor', { cursor: cursorDate });
    }

    const items = await qb
      .orderBy('skill.createdAt', 'DESC')
      .take(limit)
      .getMany();

    const hasNextPage = items.length > pagination.limit;
    const pageItems = hasNextPage ? items.slice(0, -1) : items;

    // Get total count for display purposes (not required for cursor pagination but useful).
    const countQb = this.skillRepository
      .createQueryBuilder('skill')
      .where('skill.isActive = :active', { active: true })
      .andWhere('skill.userId != :uid', { uid: currentUserId });

    if (query && query.trim()) {
      countQb.andWhere(
        '(LOWER(skill.title) LIKE :q OR LOWER(skill.description) LIKE :q)',
        { q: `%${query.toLowerCase()}%` },
      );
    }
    if (category && category !== 'All') {
      countQb.andWhere('skill.category = :category', { category });
    }
    if (type && (type === SkillType.OFFER || type === SkillType.WANT)) {
      countQb.andWhere('skill.type = :type', { type });
    }

    const totalCount = await countQb.getCount();

    const edges: SkillEdge[] = pageItems.map((item) => ({
      node: item,
      cursor: Buffer.from(item.createdAt.toISOString()).toString('base64'),
    }));

    const endCursor =
      edges.length > 0 ? edges[edges.length - 1].cursor : undefined;

    return {
      edges,
      pageInfo: { hasNextPage, endCursor },
      totalCount,
    };
  }

  async addPortfolio(
    userId: string,
    input: AddPortfolioInput,
  ): Promise<Portfolio> {
    await this.assertNotGuest(userId);
    const skill = await this.skillRepository.findOne({
      where: { id: input.skillId, userId },
    });
    if (!skill) throw new NotFoundException('Skill not found or unauthorized');

    const portfolio = this.portfolioRepository.create(input);
    return this.portfolioRepository.save(portfolio);
  }

  async removePortfolio(userId: string, id: string): Promise<boolean> {
    await this.assertNotGuest(userId);
    const portfolio = await this.portfolioRepository.findOne({
      where: { id },
      relations: ['skill'],
    });

    if (!portfolio || portfolio.skill.userId !== userId) {
      throw new NotFoundException('Portfolio item not found or unauthorized');
    }

    await this.portfolioRepository.remove(portfolio);
    return true;
  }

  async updatePortfolio(
    userId: string,
    id: string,
    input: UpdatePortfolioInput,
  ): Promise<Portfolio> {
    await this.assertNotGuest(userId);
    const portfolio = await this.portfolioRepository.findOne({
      where: { id },
      relations: ['skill'],
    });

    if (!portfolio || portfolio.skill.userId !== userId) {
      throw new NotFoundException('Portfolio item not found or unauthorized');
    }

    Object.assign(portfolio, input);
    return this.portfolioRepository.save(portfolio);
  }

  async findManyByIds(ids: readonly string[]): Promise<Skill[]> {
    return this.skillRepository.find({ where: { id: In(ids) } });
  }
}
